(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-146":{scenario:{company:"Silverleaf Packaging JSC",supervisor:{name:"Lương Bích Ngọc",role:{vi:"Giám đốc Tài chính",en:"Chief Financial Officer"}},ref_code:"CFW-2647",title:{vi:"Tiền thật. Dòng tiền thật. Phê duyệt thật.",en:"Real cash. Real flows. Real approvals."},brief:{vi:"Bạn lập dự báo dòng tiền tuần 47 (hồ sơ CFW-2647). Số dư tiền và tương đương tiền đầu tuần 18400 triệu đồng, chưa gồm hợp đồng tiền gửi TD-608 trị giá 10000 triệu đồng, kỳ hạn gốc 6 tháng, còn 5 tháng. Thu dự kiến 26350 triệu, chi dự kiến 41200 triệu; số dư tối thiểu theo chính sách 5000 triệu đồng. Bản nháp tính TD-608 là tiền khả dụng. Hãy sửa phân loại TD-608 và số tiền cần rút hạn mức tín dụng, rồi lập báo cáo.",en:"You are building the week 47 cash forecast (file CFW-2647). Opening cash and cash equivalents are 18400 million VND, excluding term deposit TD-608 of 10000 million VND with a 6-month original term and 5 months left. Expected receipts 26350 million, expected payments 41200 million; the policy minimum balance is 5000 million VND. The draft counts TD-608 as available cash. Correct the TD-608 classification and the credit line drawdown, then report."},reference_title:{vi:"Chính sách ngân quỹ & mẫu dự báo đã duyệt · CFW-2647",en:"Approved treasury policy & forecast template · CFW-2647"},fields:[{id:"TD608_CLASS",label:{vi:"Phân loại tiền gửi TD-608",en:"TD-608 classification"},initial:"CASH_EQ",expected:"HTM",choices:["CASH","CASH_EQ","HTM"],reference:"Chính sách phân loại tiền và đầu tư",ref_value:{vi:"Tương đương tiền: kỳ hạn gốc không quá 3 tháng; dài hơn: đầu tư nắm giữ đến ngày đáo hạn (HTM)",en:"Cash equivalent: original maturity of 3 months or less; longer: held-to-maturity investment (HTM)"},hint:{vi:"Xét kỳ hạn gốc tại ngày gửi, không xét thời gian còn lại của hợp đồng.",en:"Look at the original term on the placement date, not the time left on the contract."}},{id:"DRAWDOWN",label:{vi:"Số tiền rút hạn mức (triệu đồng)",en:"Credit line drawdown (million VND)"},initial:"0",expected:"1450",reference:"Mẫu dự báo dòng tiền 13 tuần",ref_value:{vi:"Tiền khả dụng đầu tuần 18400; thu 26350; chi 41200; số dư tối thiểu 5000 (triệu đồng)",en:"Available opening cash 18400; receipts 26350; payments 41200; minimum balance 5000 (million VND)"},hint:{vi:"Chỉ cộng tiền khả dụng; phần thiếu so với số dư tối thiểu là số cần rút hạn mức.",en:"Add only available cash; the shortfall against the minimum balance is the drawdown."}}],sop32:{vi:"Số dư cuối tuần = tiền khả dụng đầu tuần + thu - chi; nếu thấp hơn số dư tối thiểu thì rút hạn mức đúng bằng phần thiếu, không tất toán trước hạn tiền gửi có kỳ hạn.",en:"Closing balance = available opening cash + receipts - payments; if below the minimum balance, draw the credit line by exactly the shortfall and do not break term deposits."},context:{label:"TMS / CFW-2647",metrics:[{label:{vi:"Tiền khả dụng đầu tuần",en:"Available opening cash"},value:"18,400,000,000 VND"},{label:{vi:"Chi dự kiến",en:"Expected payments"},value:"41,200,000,000 VND"},{label:{vi:"Số dư tối thiểu",en:"Minimum balance"},value:"5,000,000,000 VND"}]},crisis:{vi:"Một email từ địa chỉ trông giống hệt của Tổng giám đốc: “Chuyển gấp 3 tỷ đồng sang tài khoản mới của nhà cung cấp ở nước ngoài trước 15:00. Giao dịch bảo mật, không cần chờ phê duyệt kép, tôi sẽ ký bù sau.”",en:"An email from an address that looks exactly like the CEO's: “Urgently wire 3 billion VND to the supplier's new overseas account before 15:00. It is confidential, skip dual approval, I will sign afterwards.”"},options:{safe:{vi:"Không chuyển tiền; gọi lại Tổng giám đốc và nhà cung cấp qua số điện thoại đã lưu, giữ phê duyệt kép, báo Giám đốc Tài chính và bộ phận an ninh thông tin.",en:"Do not pay; call the CEO and the supplier back on numbers on file, keep dual approval, and alert the CFO and the information security team."},shortcut:{vi:"Chuyển ngay cho kịp giờ vì email ghi rõ là lệnh của Tổng giám đốc.",en:"Pay now to meet the deadline because the email says it is the CEO's order."},wait:{vi:"Để email đó lại, không xác minh và không báo cho ai.",en:"Leave the email alone, neither verify it nor tell anyone."}},questions:{vi:["Vì sao TD-608 không được tính vào tiền khả dụng và số rút hạn mức 1450 triệu đồng được tính như thế nào?","Nêu các bước kiểm soát để phòng lừa đảo email giả mạo lãnh đạo (BEC) trong quy trình thanh toán."],en:["Why is TD-608 excluded from available cash and how did you calculate the 1450 million VND drawdown?","List the controls that prevent business email compromise (BEC) fraud in the payment process."]},hints:{vi:["Đối chiếu kỳ hạn gốc của TD-608 với định nghĩa tương đương tiền trong chính sách.","Tính số dư cuối tuần chỉ với tiền khả dụng, rồi so với số dư tối thiểu ở SOP mục 3.2.","Đọc SOP mục 4.2: lệnh chuyển tiền bất thường phải được xác minh qua kênh độc lập trước khi thực hiện."],en:["Compare TD-608's original term with the cash equivalent definition in the policy.","Compute the closing balance with available cash only, then compare it with the minimum balance in SOP 3.2.","Re-read SOP 4.2: unusual payment orders must be verified through an independent channel before execution."]}},learning:{summary:{vi:"Chuyên viên quản lý ngân quỹ và dòng tiền bảo đảm doanh nghiệp luôn đủ tiền thanh toán với chi phí vốn thấp nhất: dự báo dòng tiền, quản lý số dư tài khoản ngân hàng, hạn mức tín dụng, tiền gửi có kỳ hạn, rủi ro tỷ giá và lãi suất, đồng thời kiểm soát quy trình thanh toán an toàn. Nghề đòi hỏi độ chính xác, kỷ luật phê duyệt và luôn cảnh giác với gian lận.",en:"A treasury and cash management specialist keeps the company able to pay its obligations at the lowest cost of funds: forecasting cash, managing bank balances, credit lines, term deposits, FX and interest rate risk, and controlling a secure payment process. The role requires accuracy, approval discipline and constant alertness to fraud."},responsibilities:{vi:["Lập và cập nhật dự báo dòng tiền 13 tuần, đối chiếu thực tế với kế hoạch.","Quản lý số dư tài khoản, gom vốn và điều chuyển tiền giữa các ngân hàng.","Sử dụng hạn mức tín dụng, gửi tiền có kỳ hạn tối ưu chi phí và lợi suất.","Đo lường và phòng ngừa rủi ro tỷ giá, lãi suất theo chính sách đã duyệt.","Kiểm soát lệnh thanh toán, phân quyền ký duyệt và phòng chống gian lận."],en:["Build and update the 13-week cash forecast and compare actuals with plan.","Manage account balances, pool and move cash between banks.","Use credit lines and term deposits to optimise cost and yield.","Measure and hedge FX and interest rate risk under the approved policy.","Control payment orders, signing authorities and fraud prevention."]},competencies:[{name:{vi:"Dự báo dòng tiền",en:"Cash forecasting"},desc:{vi:"Ước tính thu chi theo tuần từ công nợ, đơn hàng, lịch trả nợ và giải thích chênh lệch.",en:"Estimate weekly receipts and payments from receivables, orders and debt schedules and explain variances."}},{name:{vi:"Quản lý thanh khoản",en:"Liquidity management"},desc:{vi:"Giữ số dư tối thiểu, chọn đúng nguồn bù thiếu hụt và đầu tư phần tiền nhàn rỗi.",en:"Hold the minimum balance, pick the right funding source and invest idle cash."}},{name:{vi:"Phòng ngừa rủi ro tài chính",en:"Financial risk hedging"},desc:{vi:"Dùng hợp đồng kỳ hạn, hoán đổi để cố định chi phí tỷ giá, lãi suất khi cần.",en:"Use forwards and swaps to fix FX and interest costs when needed."}},{name:{vi:"Kiểm soát thanh toán",en:"Payment control"},desc:{vi:"Áp dụng phê duyệt kép, xác minh độc lập và phát hiện dấu hiệu lừa đảo email.",en:"Apply dual approval, independent verification and spot email fraud red flags."}},{name:{vi:"Quan hệ ngân hàng",en:"Bank relationships"},desc:{vi:"Đàm phán hạn mức, phí, lãi suất và theo dõi cam kết tín dụng với các ngân hàng.",en:"Negotiate lines, fees and rates and track loan covenants with banks."}}],knowledge:{vi:["VAS 24 và IAS 7 về báo cáo lưu chuyển tiền tệ, định nghĩa tiền và các khoản tương đương tiền.","Thông tư 200/2014/TT-BTC về chế độ kế toán doanh nghiệp: tiền gửi ngân hàng, tiền gửi có kỳ hạn, đầu tư nắm giữ đến ngày đáo hạn.","Quản trị vốn lưu động: chu kỳ chuyển đổi tiền mặt (CCC), DSO, DIO, DPO.","Công cụ phòng ngừa rủi ro tỷ giá, lãi suất: hợp đồng kỳ hạn, hoán đổi, quyền chọn.","Quy định quản lý ngoại hối hiện hành khi thanh toán cho đối tác nước ngoài.","Kiểm soát thanh toán: phân quyền, phê duyệt kép, xác minh độc lập và phòng chống lừa đảo BEC."],en:["VAS 24 and IAS 7 on cash flow statements and the definition of cash and cash equivalents.","Circular 200/2014/TT-BTC on corporate accounting: bank deposits, term deposits and held-to-maturity investments.","Working capital management: cash conversion cycle (CCC), DSO, DIO, DPO.","FX and interest rate hedging tools: forwards, swaps and options.","Current foreign exchange rules for payments to overseas counterparties.","Payment controls: authority matrix, dual approval, independent verification and BEC fraud prevention."]},tools:["Treasury Management System (TMS)","Corporate e-banking","ERP cash & AP/AR modules","Bank statement feeds (MT940)","Spreadsheet cash models","FX dealing platform"],tools_en:["Treasury Management System (TMS)","Corporate e-banking","ERP cash & AP/AR modules","Bank statement feeds (MT940)","Spreadsheet cash models","FX dealing platform"],kpis:{vi:["Sai số dự báo dòng tiền tuần so với thực tế.","Số ngày số dư thấp hơn mức tối thiểu (mục tiêu bằng 0).","Chi phí vốn bình quân và lợi suất tiền nhàn rỗi.","Số lệnh thanh toán sai hoặc bị lừa đảo (mục tiêu bằng 0)."],en:["Weekly cash forecast error versus actuals.","Days below the minimum balance (target zero).","Average cost of funds and yield on idle cash.","Erroneous or fraudulent payments (target zero)."]},day:[{time:"08:00",vi:"Tải sao kê ngân hàng, đối chiếu số dư thực tế với dự báo hôm qua.",en:"Load bank statements and reconcile actual balances with yesterday's forecast."},{time:"09:30",vi:"Cập nhật dự báo dòng tiền tuần, quyết định rút hạn mức hoặc gửi tiền.",en:"Update the weekly forecast and decide on drawdowns or deposits."},{time:"11:00",vi:"Lấy báo giá tỷ giá kỳ hạn cho khoản phải trả ngoại tệ sắp đến hạn.",en:"Get forward FX quotes for upcoming foreign currency payables."},{time:"14:00",vi:"Kiểm tra và trình duyệt lô lệnh thanh toán nhà cung cấp theo phân quyền.",en:"Check and submit the supplier payment batch under the authority matrix."},{time:"16:30",vi:"Báo cáo vị thế tiền cuối ngày cho Giám đốc Tài chính.",en:"Report the end-of-day cash position to the CFO."}],mistakes:{vi:["Tính tiền gửi kỳ hạn trên 3 tháng vào tiền khả dụng, che giấu thiếu hụt thanh khoản.","Quên số dư tối thiểu và các khoản chi cố định khi tính nhu cầu vốn.","Thực hiện lệnh chuyển tiền gấp qua email mà không xác minh qua kênh độc lập."],en:["Counting term deposits over 3 months as available cash, hiding a liquidity gap.","Forgetting the minimum balance and fixed payments when sizing funding needs.","Executing an urgent email payment order without independent verification."]},career:[{vi:"Nhân viên ngân quỹ",en:"Treasury assistant"},{vi:"Chuyên viên quản lý ngân quỹ & dòng tiền",en:"Treasury & cash management specialist"},{vi:"Trưởng phòng Ngân quỹ",en:"Treasury manager"},{vi:"Giám đốc Ngân quỹ / Giám đốc Tài chính",en:"Group treasurer / CFO"}],glossary:[{term:"Cash equivalent",vi:"Khoản đầu tư ngắn hạn, dễ chuyển đổi thành tiền, ít rủi ro, thường có kỳ hạn gốc không quá 3 tháng.",en:"A short-term, highly liquid investment with insignificant risk, usually with an original maturity of 3 months or less."},{term:"Cash forecast",vi:"Bảng dự báo thu chi và số dư tiền theo ngày, tuần hoặc tháng.",en:"A projection of receipts, payments and cash balances by day, week or month."},{term:"Revolving credit line",vi:"Hạn mức tín dụng quay vòng cho phép rút, trả và rút lại trong thời hạn hạn mức.",en:"A credit facility that can be drawn, repaid and redrawn during its term."},{term:"CCC",vi:"Chu kỳ chuyển đổi tiền mặt = DSO + DIO - DPO, thời gian vốn bị giữ trong vòng kinh doanh.",en:"Cash conversion cycle = DSO + DIO - DPO, the time cash is tied up in operations."},{term:"BEC",vi:"Lừa đảo xâm phạm email doanh nghiệp: giả danh lãnh đạo hoặc nhà cung cấp để yêu cầu chuyển tiền.",en:"Business email compromise: impersonating executives or suppliers to request payments."}],quiz:[{q:{vi:"Khoản nào được coi là tương đương tiền?",en:"Which item qualifies as a cash equivalent?"},options:{vi:["Tiền gửi kỳ hạn gốc 6 tháng","Cổ phiếu niêm yết","Khoản phải thu khách hàng","Tiền gửi kỳ hạn gốc 2 tháng, dễ chuyển đổi, ít rủi ro"],en:["A deposit with a 6-month original term","Listed shares","Trade receivables","A deposit with a 2-month original term, liquid and low risk"]},answer:3,explain:{vi:"Tương đương tiền thường có kỳ hạn gốc không quá 3 tháng và rủi ro thay đổi giá trị không đáng kể.",en:"Cash equivalents usually have an original maturity of 3 months or less and insignificant risk of value change."}},{q:{vi:"Tiền khả dụng 12000, thu 8000, chi 17000, số dư tối thiểu 4000 (triệu đồng). Cần rút hạn mức bao nhiêu?",en:"Available cash 12000, receipts 8000, payments 17000, minimum balance 4000 (million VND). How much must be drawn?"},options:{vi:["1000 triệu","3000 triệu","Không cần rút","4000 triệu"],en:["1000 million","3000 million","No drawdown","4000 million"]},answer:0,explain:{vi:"Số dư cuối = 12000 + 8000 - 17000 = 3000; thiếu 4000 - 3000 = 1000 triệu đồng.",en:"Closing = 12000 + 8000 - 17000 = 3000; shortfall 4000 - 3000 = 1000 million."}},{q:{vi:"Doanh nghiệp có khoản phải trả 500000 USD sau 3 tháng và muốn cố định chi phí VND. Công cụ phù hợp là gì?",en:"The company owes 500000 USD in 3 months and wants to fix the VND cost. Which tool fits?"},options:{vi:["Bán kỳ hạn USD","Gửi tiết kiệm VND","Mua kỳ hạn USD giao sau 3 tháng","Không làm gì"],en:["Sell USD forward","Place a VND deposit","Buy USD forward for delivery in 3 months","Do nothing"]},answer:2,explain:{vi:"Khoản phải trả ngoại tệ được phòng ngừa bằng hợp đồng mua kỳ hạn ngoại tệ đúng kỳ hạn thanh toán.",en:"A foreign currency payable is hedged by buying that currency forward for the payment date."}},{q:{vi:"Nhận email “lãnh đạo” yêu cầu chuyển tiền gấp sang tài khoản mới. Bước đúng đầu tiên là gì?",en:"An “executive” email asks for an urgent transfer to a new account. What is the right first step?"},options:{vi:["Chuyển ngay để tránh bị phê bình","Xác minh qua số điện thoại đã lưu và giữ phê duyệt kép","Trả lời chính email đó để hỏi lại","Chuyển một nửa trước"],en:["Pay at once to avoid criticism","Verify via the phone number on file and keep dual approval","Reply to the same email to ask","Pay half first"]},answer:1,explain:{vi:"Kẻ gian kiểm soát email nên phải xác minh qua kênh độc lập đã lưu sẵn và không bỏ phê duyệt kép.",en:"Fraudsters control the email thread, so verify through an independent channel on file and never skip dual approval."}}]}}})})(window.KKR);
